return (() => {
  // Strategy 1: look for existing node card with 图文上传
  const allEls = document.querySelectorAll('*');
  for (const el of allEls) {
    const t = (el.textContent || '').trim();
    if (t === '图文上传' && el.children.length === 0) {
      const rect = el.getBoundingClientRect();
      if (rect.width > 0 && rect.height > 0) {
        el.click();
        return { clicked: true, strategy: 'existing_node', tag: el.tagName };
      }
    }
  }
  // Strategy 2: no existing node found, click "新增节点"
  const btns = Array.from(document.querySelectorAll('button, [role=button], .ant-card-extra *'));
  const addBtn = btns.find(b => (b.textContent || '').trim().includes('新增节点'));
  if (addBtn) {
    addBtn.click();
    return { clicked: true, strategy: 'add_new_node' };
  }
  // Strategy 3: try clickText approach
  for (const el of allEls) {
    const t = (el.textContent || '').trim();
    if (t.includes('图文上传') && el.children.length <= 2 && el.closest('[class*=node], [class*=Node], [class*=card], [class*=Card]')) {
      el.click();
      return { clicked: true, strategy: 'node_card_match' };
    }
  }
  return { clicked: false };
})()

return (() => {
  // If we clicked "新增节点", a modal should appear with node type options
  const modal = document.querySelector('.ant-modal:not(.ant-modal-hidden)');
  if (modal) {
    // Look for 图文上传 option
    const items = Array.from(modal.querySelectorAll('[class*=item], [class*=card], li, .ant-list-item, .ant-card'));
    for (const item of items) {
      const t = (item.textContent || '').trim();
      if (t.includes('图文上传') || t.includes('图文')) {
        item.click();
        return { selected: true, text: t.substring(0, 40) };
      }
    }
    // If not found, try any element containing the text
    const allEls = modal.querySelectorAll('*');
    for (const el of allEls) {
      const t = (el.textContent || '').trim();
      if (t === '图文上传' && el.children.length === 0) {
        el.click();
        return { selected: true, text: t };
      }
    }
    return { selected: false, modalText: (modal.textContent || '').substring(0, 200) };
  }
  // No modal - node was already clicked
  return { selected: false, reason: 'no_modal' };
})()
